{
  "PROP-6a4369e9-inv-039": {
    "property_id": "PROP-6a4369e9-inv-039",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-039",
      "classification": "potential-vulnerability",
      "code_path": "beacon_node/network/src/network_beacon_processor/gossip_methods.rs::process_gossip_data_column_sidecar::L745-765",
      "proof_trace": "IGNORE validation prevents forwarding (correct) but lacks explicit re-processing queue. Messages with FutureSlot/PastFinalizedSlot errors return IGNORE without application-level re-queuing, unlike ParentUnknown which explicitly queues for sync. Proof fails on reprocessability guarantee.",
      "attack_scenario": "Attacker sends data columns just outside clock disparity window. Node returns IGNORE (no forward, correct) but never re-processes when slot becomes valid, causing availability failures if those columns are needed for reconstruction.",
      "checklist_id": "PROP-6a4369e9-inv-039"
    },
    "text": "Gossip validation IGNORE must not forward but allow later re-processing of the message.",
    "assertion": "forall msg: ignored(msg) => not_forwarded(msg) && reprocessable(msg)",
    "covers": "SG-006",
    "severity": "LOW",
    "type": "invariant"
  }
}

